'use strict';

class JSZip {
  constructor() {
    this._files = new Map();
  }

  file(name, data, options = {}) {
    if (!name) {
      throw new Error('File name is required');
    }
    const key = String(name);
    let content;
    if (Buffer.isBuffer(data)) {
      content = data;
    } else if (data instanceof Uint8Array) {
      content = Buffer.from(data);
    } else if (typeof data === 'string') {
      const binary = options.binary === true;
      content = binary ? Buffer.from(data, 'binary') : Buffer.from(data, 'utf8');
    } else if (data == null) {
      content = Buffer.alloc(0);
    } else {
      content = Buffer.from(String(data), 'utf8');
    }
    this._files.set(key, content);
    return this;
  }

  folder() {
    // Return this to support chained folder().file() usage in existing code.
    return this;
  }

  async generateAsync(options = {}) {
    const { type = 'nodebuffer' } = options;
    const boundary = '\n---JSZIP-STUB---\n';
    const serialized = Array.from(this._files.entries())
      .map(([name, buf]) => `FILE:${name}\n${buf.toString('base64')}`)
      .join(boundary);
    const buffer = Buffer.from(serialized, 'utf8');
    if (type === 'string') {
      return buffer.toString('utf8');
    }
    if (type === 'uint8array') {
      return new Uint8Array(buffer);
    }
    return buffer;
  }
}

module.exports = JSZip;
module.exports.default = JSZip;
module.exports.JSZip = JSZip;
